class Solution:

	def tour(self, lis, n):
		balance = 0
		kami = 0
		start = 0
		for i in range(n):
			petrol = lis[i][0]
			dis = lis[i][1]
			balance = petrol - dis + balance
			if balance < 0:
				kami = kami + balance
				balance = 0
				start = i + 1
		if balance + kami >= 0:
			return start
		else:
			return -1
